-- Entrance checkpoint (creature_entry 0) for every dungeon and raid, at the instance's own entrance
-- areatrigger_teleport target. Scarlet Monastery, Stratholme and Dire Maul get one row per wing entrance
-- (location_index); a player respawns at the one nearest where they died. Not covered: Utgarde Keep (574, set up
-- in b_dungeon_checkpoint_location.sql) and the Eye of Eternity (616, its platform is destroyed in phase 3).
DELETE FROM `dungeon_checkpoint_location` WHERE `creature_entry` = 0 AND `map_id` IN (33, 34, 36, 43, 47, 48, 70, 90, 109, 129, 189, 209, 229, 230, 249, 269, 289, 309, 329, 349, 389, 409, 429, 469, 509, 531, 532, 533, 534, 540, 542, 543, 544, 545, 546, 547, 548, 550, 552, 553, 554, 555, 556, 557, 558, 560, 564, 565, 568, 575, 576, 578, 580, 585, 595, 599, 600, 601, 602, 603, 604, 608, 615, 619, 624, 631, 632, 649, 650, 658, 668, 724);
